using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using Microsoft.AspNetCore.Identity;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Sem.Web.Core;
using Sem.Web.Data;
using Sem.Web.Runtime;
var root=Path.Combine(Path.GetTempPath(),"sem-questions-"+Guid.NewGuid());Directory.CreateDirectory(root);
var services=new ServiceCollection();services.AddLogging();services.AddDbContextFactory<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+Path.Combine(root,"data.db")),ServiceLifetime.Scoped);services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();services.AddSingleton(TimeProvider.System);Microsoft.Extensions.DependencyInjection.DataProtectionServiceCollectionExtensions.AddDataProtection(services);services.AddSingleton<BusinessNotificationStore>();services.AddScoped<CoreFoundationService>();using var provider=services.BuildServiceProvider();using var scope=provider.CreateScope();var factory=scope.ServiceProvider.GetRequiredService<IDbContextFactory<ApplicationDbContext>>();var core=scope.ServiceProvider.GetRequiredService<CoreFoundationService>();int passed=0;
void Check(bool v,string label){if(!v)throw new Exception(label);passed++;Console.WriteLine("PASS "+label);}
async Task Deny<T>(Func<Task> f,string label)where T:Exception{bool denied=false;try{await f();}catch(T){denied=true;}Check(denied,label);}
ClaimsPrincipal Who(string id)=>new(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,id),new Claim("AspNet.Identity.SecurityStamp",id+"-stamp"),new Claim(PasskeyAdditionService.SessionClaim,id+"-session")],"Identity.Application"));
EventQuestionPlanEdit Edit(EventQuestionPlan p,params EventQuestionEdit[] rows)=>new(p.RowVersion,rows);
EventQuestionEdit Row(EventQuestionView q)=>new(q.Id,q.Text,q.Type,q.Required,q.Disabled,q.Public,q.PublicText);
try{
 await using(var db=await factory.CreateDbContextAsync()){
  await db.GetService<IMigrator>().MigrateAsync("20261012201328_AddPartDefinitions");
  foreach(var userId in new[]{"admin","manager","member"})db.Users.Add(new ApplicationUser{Id=userId,Email=userId+"@test",UserName=userId+"@test",DisplayName=userId,Enabled=true,EmailConfirmed=true,SecurityStamp=userId+"-stamp",IsAdmin=userId=="admin"});
  var e=new SessionEvent{Id="old",Title="Retained",ScheduledDate="2026-11-01T00:00:00.000Z",CreatedAt="2026-10-01T00:00:00.000Z",RowVersion=7};e.Admins.Add(new(){EventId=e.Id,UserId="manager",GrantedAt=e.CreatedAt});e.Phases.Add(new(){EventId=e.Id,Kind="Hidden",Name="非表示",IsActive=true});e.Phases.Add(new(){EventId=e.Id,Kind="View",Name="閲覧",SortOrder=1});await db.SaveChangesAsync();await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO SessionEvents (Id,Title,Description,Location,ScheduledDate,AnnouncementMessage,PhaseKind,ManualPhaseOverride,CreatedAt,RowVersion) VALUES ({e.Id},{e.Title},{e.Description},{e.Location},{e.ScheduledDate},{e.AnnouncementMessage},{e.PhaseKind},{e.ManualPhaseOverride},{e.CreatedAt},{e.RowVersion})");db.EventAdmins.AddRange(e.Admins);db.Phases.AddRange(e.Phases);db.EventPartDefinitions.Add(new(){Id="preserved-part",EventId=e.Id,Name="Vo",NormalizedName="VO",Category="Sing"});await db.SaveChangesAsync();await SqliteStorageInitializer.InitializeAsync(db);
 }
 var admin=Who("admin");var manager=Who("manager");var member=Who("member");var plan=await core.ReadQuestionsAsync(manager,"old");
 Check(plan.Questions.Length==0&&plan.RowVersion==7&&plan.Title=="Retained","Definition-schema migration introduces no invented questions or event-version changes");
 await using(var db=await factory.CreateDbContextAsync())Check(await db.Users.CountAsync()==3&&await db.PartPresets.CountAsync()==6&&await db.EventPartDefinitions.AnyAsync(p=>p.Id=="preserved-part")&&await db.Phases.CountAsync()==2&&await db.EventAdmins.CountAsync()==1,"Migration preserves users presets event definitions phases managers");
 await Deny<UnauthorizedAccessException>(()=>core.ReadQuestionsAsync(member,"old"),"Member cannot inspect private management questionnaire");await Deny<UnauthorizedAccessException>(()=>core.SaveQuestionsAsync(member,"old",Edit(plan,[])),"Member cannot write question management");await Deny<UnauthorizedAccessException>(()=>core.ReadQuestionsAsync(manager,"unknown"),"Unknown event is not a public management surface");
 var yes=new EventQuestionEdit(Guid.NewGuid().ToString(),"Bring instrument?","YesNo",true);var text=new EventQuestionEdit(Guid.NewGuid().ToString(),"Notes","Text");
 await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes with{Text=" "}])),"Empty question text rejected");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes with{Text=new string('x',201)}])),"Question length limit enforced");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes with{Type="Password"}])),"Unknown answer type rejected");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,yes])),"Duplicate question IDs rejected");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes with{Public=true,PublicText=true}])),"YesNo cannot expose a text body");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[text with{PublicText=true}])),"Body exposure without public aggregate rejected");
 plan=await core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,text]));Check(plan.Questions.Length==2&&plan.Questions.All(q=>!q.Public&&!q.PublicText)&&plan.Questions[0].Required,"Creation defaults private and saves required flag");
 await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes with{Type="Text"},text])),"Answer type is immutable even before any answer");await Deny<CoreConflictException>(()=>core.SaveQuestionsAsync(manager,"old",new(plan.RowVersion-1,[yes,text])),"Stale questionnaire save cannot overwrite another manager");
 var other=await core.SaveEventAsync(admin,null,new("Other","","",DateTimeOffset.UtcNow.AddDays(2),null,"","Hidden",[],0));var foreign=await core.ReadQuestionsAsync(admin,other);await Deny<UnauthorizedAccessException>(()=>core.SaveQuestionsAsync(manager,other,Edit(foreign,[yes])),"Unassigned event manager cannot edit another event");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(admin,other,Edit(foreign,[yes])),"Question identity cannot move between events");
 // Synthetic storage fixtures only. No participant answer path is exposed by this unit.
 await using(var db=await factory.CreateDbContextAsync()){db.EventQuestionAnswers.AddRange(new(){QuestionId=yes.Id,UserId="member",Value="NO",UpdatedAt="2026-10-13T00:00:00.000Z"},new(){QuestionId=text.Id,UserId="member",Value=null,UpdatedAt="2026-10-13T00:00:00.000Z"});await db.SaveChangesAsync();}
 plan=await core.ReadQuestionsAsync(manager,"old");Check(plan.Questions.All(q=>q.AnswerCount==1),"Manager sees counts without receiving answer values");await using(var db=await factory.CreateDbContextAsync())Check((await db.EventQuestionAnswers.SingleAsync(a=>a.QuestionId==yes.Id)).Value=="NO"&&(await db.EventQuestionAnswers.SingleAsync(a=>a.QuestionId==text.Id)).Value is null,"NO and unanswered storage are distinct and not coerced to false");
 await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[])),"Answered questions cannot be removed");Check((await core.ReadQuestionsAsync(manager,"old")).RowVersion==plan.RowVersion,"Rejected removal changes neither questions nor event version");
 var stopped=await core.SaveQuestionsAsync(manager,"old",Edit(plan,[text with{Required=true,Disabled=true,Public=true,PublicText=true},yes with{Text="Updated label",Disabled=true}]));Check(stopped.Questions[0].Id==text.Id&&stopped.Questions.All(q=>q.Disabled)&&stopped.Questions[0].PublicText,"Answered questions can rename reorder stop and retain independent public settings");await using(var db=await factory.CreateDbContextAsync())Check(await db.EventQuestionAnswers.CountAsync()==2&&(await db.EventQuestionAnswers.SingleAsync(a=>a.QuestionId==yes.Id)).Value=="NO","Definition edits retain all answer storage without reinterpretation");
 plan=await core.SaveQuestionsAsync(manager,"old",Edit(stopped,[yes,text]));Check(plan.Questions.All(q=>!q.Disabled&&!q.Public&&!q.PublicText),"Stopped questions resume without erasing answers and publication can be revoked");
 var draft=new EventQuestionEdit(Guid.NewGuid().ToString(),"Unused","Text");plan=await core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,text,draft]));plan=await core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,text]));await using(var db=await factory.CreateDbContextAsync())Check((await db.EventQuestions.SingleAsync(q=>q.Id==draft.Id)).DeletedAt is not null,"Unanswered removal retains a tombstone");await Deny<ValidationException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,text,draft])),"Deleted question identity cannot be resurrected");
 var definitions=await core.ReadDefinitionsAsync(manager,"old");await core.SaveDefinitionsAsync(manager,"old",new(definitions.RowVersion,definitions.Definitions.Select(d=>new PartDefinitionEdit(d.Id,d.Name,d.Category)).ToArray()));await Deny<CoreConflictException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(plan,[yes,text])),"Definition save shares event concurrency with question drafts");
 var race=await core.ReadQuestionsAsync(admin,"old");async Task<bool> Race(string value){try{await core.SaveQuestionsAsync(admin,"old",Edit(race,[yes with{Text=value},text]));return true;}catch(CoreConflictException){return false;}}var races=await Task.WhenAll(Task.Run(()=>Race("RaceA")),Task.Run(()=>Race("RaceB")));Check(races.Count(v=>v)==1,"Concurrent manager question plans commit once");
 await using(var db=await factory.CreateDbContextAsync()){db.EventQuestions.Remove(await db.EventQuestions.SingleAsync(q=>q.Id==yes.Id));await Deny<DbUpdateException>(()=>db.SaveChangesAsync(),"Database FK refuses physically deleting an answered question");}
 await using(var db=await factory.CreateDbContextAsync()){db.EventQuestionAnswers.Add(new(){QuestionId=yes.Id,UserId="missing",Value="YES"});await Deny<DbUpdateException>(()=>db.SaveChangesAsync(),"Answer storage requires a real retained user");}
 await using(var db=await factory.CreateDbContextAsync()){db.RevokedAuthSessions.Add(new(){TokenHash=SemEndpoints.Hash("manager-session"),UserId="manager",RevokedAt="2026-10-01T00:00:00.000Z"});await db.SaveChangesAsync();}
 var latest=await core.ReadQuestionsAsync(admin,"old");await Deny<UnauthorizedAccessException>(()=>core.SaveQuestionsAsync(manager,"old",Edit(latest,latest.Questions.Select(Row).ToArray())),"Revoked connected-session identity cannot change questions");
 await using(var db=await factory.CreateDbContextAsync()){await SqliteStorageInitializer.InitializeAsync(db);Check(await db.EventQuestionAnswers.CountAsync()==2&&await db.Users.CountAsync()==3,"Restart retains question answer references and identities");Check(!db.Database.HasPendingModelChanges(),"EF model matches question migration");}
 Console.WriteLine("Question checks passed: "+passed);
}finally{SqliteConnection.ClearAllPools();Directory.Delete(root,true);}
